    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "Acceptable for general warranties only (target 25–30%); carve out everything else"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "AUD 10k de minimis; tipping basket around 0.5% (AUD 120k); related claims aggregate"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PARTIAL",
      "evidence": "General warranties: 18–24 months, so the Buyer gets at least one full audit cycle."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "100% cap, no thresholds, no disclosure/knowledge qualification, 7 years"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Expressly carve out of all limitations: fraud, dishonesty and wilful concealment by the Seller, its officers or its advisers"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Delete general disclosure of the data room."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Preferred position: delete it and include an express statement that the Buyer's knowledge does not reduce warranty claims"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "The Buyer may waive the condition; the Seller may not deem it satisfied."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Deeds of release and PPSR and other security discharges are Completion deliverables."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Treat the bonuses and all associated on-costs as Transaction Expenses / Debt and deduct them from the price."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Broaden the specific indemnity to all Loss arising from any Ironquay claim or any failure of the company to own the SOW3 materials."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Full file and NDB assessment now; resolve pre-Completion; specific indemnity; retention"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Full particulars; leakage if related party; debt-like if accrued; terminate if unnecessary"
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Specific indemnities: their own periods, tied to the underlying risk."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Independent searches; full title deliverables; fundamental warranty"
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Standalone tax indemnity; Ironquay covered by indemnity"
    }
  ],
  "adopts_framing": true,
  "adopts_framing_evidence": "20% is within the commonly seen range for general warranties, so this is not the main fight.",
  "names_manipulation": true
}

